  const scenes = { 1: q('[data-scene="1"]'), 2: q('[data-scene="2"]'), 3: q('[data-scene="3"]'), 4: q('[data-scene="4"]') };
  const shots = { 1: q('[data-shot="1"]'), 2: q('[data-shot="2"]'), 3: q('[data-shot="3"]') };
  const pb = q('#pb');
  const TOTAL = 18000; // 18s — vertical attention budget
  const TL = [
    { t: 0,     a: () => { setScene(1); } },
    { t: 3200,  a: () => { setScene(2); } },
    { t: 6200,  a: () => { setScene(3); setShot(1); } },
    { t: 8800,  a: () => { setShot(2); } },
    { t: 11400, a: () => { setShot(3); } },
    { t: 13800, a: () => { setScene(4); } },
    { t: 18000, a: () => { loop(); } },
  ];
  let timers = [], start = performance.now();
  function setScene(n) { Object.entries(scenes).forEach(([k, el]) => el.classList.toggle('active', +k === n)); }
  function setShot(n) { Object.entries(shots).forEach(([k, el]) => el.classList.toggle('active', +k === n)); }
  function reset() { Object.values(scenes).forEach(el => el.classList.remove('active')); Object.values(shots).forEach(el => el.classList.remove('active')); }
  function run() { reset(); timers.forEach(clearTimeout); timers = TL.map(({t,a}) => setTimeout(a, t)); }
  function loop() { start = performance.now(); run(); }
  function tick(now) { pb.style.width = `${((now - start) % TOTAL) / TOTAL * 100}%`; requestAnimationFrame(tick); }
  run(); requestAnimationFrame(tick);
  document.addEventListener('visibilitychange', () => { if (document.hidden) { timers.forEach(clearTimeout); timers = []; } else { loop(); } });
})();
</script>
