  .pill.v { background: rgba(139,124,246,0.15); color: var(--violet); }
  .pill.d { background: rgba(255,255,255,0.05); color: var(--dim); }

  .toast {
    position: absolute;
    bottom: 12px;
    left: 12px;
    right: 12px;
    padding: 10px 14px;
    background: rgba(245,166,35,0.1);
    border: 1px solid rgba(245,166,35,0.25);
    border-radius: 11px;
    font-size: 12px;
    color: var(--amber);
    text-align: center;
  }

  .chat { gap: 12px; justify-content: center; }
  .bubble {
    max-width: 82%;
    padding: 12px 15px;
    border-radius: 15px;
    font-size: 12.5px;
    line-height: 1.6;
  }
  .bubble.user {
    align-self: flex-start;
    background: rgba(255,255,255,0.05);
    border: 1px solid var(--border);
    border-bottom-right-radius: 5px;
  }
  .bubble.ai {
    align-self: flex-end;
    background: linear-gradient(135deg, rgba(245,166,35,0.12), rgba(245,166,35,0.04));
    border: 1px solid rgba(245,166,35,0.2);
    border-bottom-left-radius: 5px;
  }
  .bubble.ai strong { color: var(--amber); }

  .focus {
    align-items: center;
    justify-content: center;
    text-align: center;
    padding: 28px;
    gap: 8px;
    position: relative;
  }
  .ring {
    position: absolute;
    width: 160px; height: 160px;
    border-radius: 50%;
    border: 2px solid rgba(245,166,35,0.25);
    animation: breathe 4s ease-in-out infinite;
  }
  @keyframes breathe {
    0%, 100% { transform: scale(1); opacity: 0.6; }
    50% { transform: scale(1.08); opacity: 1; }
  }
  .focus-task { position: relative; font-size: 22px; font-weight: 600; }
  .focus-timer {
    position: relative;
    font-size: 46px;
    font-weight: 700;
    color: var(--amber);
    font-variant-numeric: tabular-nums;
  }
  .focus-sub { position: relative; font-size: 12px; color: var(--dim); }

  /* ── مشهد 4: CTA ── */
  .cta {
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: 24px;
    text-align: center;
    padding: 0 28px;
    max-width: 560px;
  }
  .cta-logo {
    display: flex;
    align-items: center;
    gap: 12px;
  }
  .cta-logo .logo { width: 42px; height: 42px; }
  .cta-logo .logo span:nth-child(2)::after { inset: 29%; border-radius: 4px; }
  .cta-logo .word {
    font-size: 22px;
    font-weight: 700;
    letter-spacing: -0.02em;
  }
  .cta h2 {
    font-size: 44px;
    font-weight: 700;
    letter-spacing: -0.03em;
    line-height: 1.15;
  }
  .cta h2 .dim { color: var(--dim); }
  .cta p {
    font-size: 15px;
    color: var(--dim);
    line-height: 1.7;
    max-width: 360px;
  }
  .cta-btn {
    display: inline-flex;
    align-items: center;
    gap: 10px;
    padding: 14px 28px;
    border-radius: 100px;
    background: var(--amber);
    color: var(--bg);
    font-size: 15px;
    font-weight: 600;
    border: none;
    box-shadow: 0 18px 36px -12px rgba(245,166,35,0.4),
                inset 0 1px 0 rgba(255,255,255,0.4);
  }

  @media (prefers-reduced-motion: reduce) {
    *, *::before, *::after {
      animation-duration: 0.01ms !important;
      transition-duration: 0.01ms !important;
    }
  }
</style>
