<script>
(function () {
  var scenes = document.querySelectorAll('.scene');
  var shots = document.querySelectorAll('.shot');
  var TOTAL = 18000;
  var timers = [];

  function setScene(n) {
    scenes.forEach(function (el) {
      el.classList.toggle('active', +el.dataset.scene === n);
    });
  }
  function setShot(n) {
    shots.forEach(function (el) {
      el.classList.toggle('active', +el.dataset.shot === n);
    });
  }
  function reset() {
    scenes.forEach(function (el) { el.classList.remove('active'); });
    shots.forEach(function (el) { el.classList.remove('active'); });
  }
  function run() {
    reset();
    timers.forEach(clearTimeout);
    timers = [
      setTimeout(function () { setScene(1); }, 0),
      setTimeout(function () { setScene(2); }, 3200),
      setTimeout(function () { setScene(3); setShot(1); }, 6200),
      setTimeout(function () { setShot(2); }, 8800),
      setTimeout(function () { setShot(3); }, 11400),
      setTimeout(function () { setScene(4); }, 13800),
      setTimeout(run, TOTAL)
    ];
  }
  run();
})();
</script>

